CREATE TABLE IF NOT EXISTS fc_runs (id TEXT PRIMARY KEY, status TEXT NOT NULL, progress REAL NOT NULL, bbox TEXT NOT NULL, window_start TEXT NOT NULL, window_end TEXT NOT NULL, window_days INTEGER NOT NULL, params TEXT NOT NULL, result TEXT, created_by TEXT, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS fc_records (id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, run_id TEXT NOT NULL, last_run_id TEXT NOT NULL, seen_count INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL, category TEXT, severity TEXT NOT NULL, area_ha REAL NOT NULL, est_date TEXT NOT NULL, date_uncertainty_days REAL, issue_date TEXT, evidence TEXT NOT NULL, score REAL, lat REAL NOT NULL, lon REAL NOT NULL, geometry TEXT NOT NULL, bbox TEXT NOT NULL, verification TEXT, authority TEXT, route TEXT, notify TEXT, notes TEXT, history TEXT, details TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fc_events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL, run_id TEXT, record_id TEXT, event_type TEXT NOT NULL, service TEXT NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL, error TEXT, actor TEXT, details TEXT);
CREATE INDEX IF NOT EXISTS ix_fc_rec_date ON fc_records(est_date);
CREATE INDEX IF NOT EXISTS ix_fc_ev_rec ON fc_events(record_id);
